// Validate schema and sanitize payload
const body = $json.body || $json;
if (!body.email || !body.name) {
  throw new Error('Invalid payload: Missing email or name');
}
return [{
  json: {
    lead_id: body.id || 'lead_' + Date.now(),
    name: body.name.trim(),
    email: body.email.trim().toLowerCase(),
    company: (body.company || '').trim(),
    message: (body.message || '').trim(),
    received_at: new Date().toISOString()
  }
}];

// Intent scoring & ICP evaluation
const lead = $json;
let score = 50;
const highValueKeywords = ['agency', 'enterprise', 'urgent', 'scale', 'pricing', 'hire', 'contract', 'team'];
const lowValueKeywords = ['student', 'free', 'internship', 'unpaid'];

const content = (lead.company + ' ' + lead.message).toLowerCase();
for (const kw of highValueKeywords) {
  if (content.includes(kw)) score += 15;
}
for (const kw of lowValueKeywords) {
  if (content.includes(kw)) score -= 25;
}

score = Math.max(0, Math.min(100, score));
const tier = score >= 75 ? 'HIGH_PRIORITY' : (score >= 45 ? 'MEDIUM_QUALIFIED' : 'NURTURE');

return [{
  json: {
    ...lead,
    lead_score: score,
    tier: tier,
    auto_book_eligible: score >= 75
  }
}];
